const Sidebar = ({ open, onClose }: { open: boolean; onClose: () => void }) => {
  const { t } = useTranslation();
  const { orders } = useAdmin();
  const pending = orders.filter((o) => o.status === 'new').length;

  return (
    <>
      {open && <div className="fixed inset-0 z-40 bg-slate-950/50 backdrop-blur-sm lg:hidden" onClick={onClose} />}
      <aside
        className={cn(
          'fixed inset-y-0 left-0 z-50 flex w-[280px] flex-col border-r bg-[var(--surface)] transition-transform duration-300 lg:translate-x-0',
          open ? 'translate-x-0' : '-translate-x-full',
        )}
        style={{ borderColor: 'var(--border)' }}
      >
        <div className="flex h-20 items-center justify-between px-5">
          <Logo />
          <button className="icon-btn lg:hidden" onClick={onClose}>
            <X size={18} />
          </button>
        </div>

        <div className="mx-4 mb-4 flex items-center gap-3 rounded-2xl border p-3" style={{ borderColor: 'var(--border)', background: 'var(--surface-2)' }}>
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-brand-500/15 text-brand-600 dark:text-brand-300">
            <Store size={18} />
          </div>
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-bold">MaxSHOP Chilonzor</p>
            <p className="flex items-center gap-1.5 text-[11px] font-semibold text-brand-600 dark:text-brand-400">
              <span className="h-1.5 w-1.5 rounded-full bg-brand-500" /> Ochiq · 08:00–22:00
            </p>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto px-3 pb-4">
          {groups.map((group) => (
            <div key={group.title} className="mb-4">
              <p className="mb-1.5 px-3 text-[10px] font-extrabold uppercase tracking-[0.16em] text-[var(--muted)]">
                {group.title}
              </p>
              <div className="space-y-1">
                {group.items.map((item) => (
                  <NavLink
                    key={item.to}
                    to={item.to}
                    end={item.end}
                    onClick={onClose}
                    className={({ isActive }) => cn('nav-link group', isActive && 'nav-link-active')}
                  >
                    <item.icon size={18} className="shrink-0" />
                    <span className="flex-1">{t(item.label)}</span>
                    {item.label === 'orders' && pending > 0 && (
                      <span className="rounded-full bg-rose-500 px-1.5 py-0.5 text-[10px] font-extrabold text-white">
                        {pending}
                      </span>
                    )}
                  </NavLink>
                ))}
              </div>
            </div>
          ))}
        </nav>

        <div className="border-t p-3" style={{ borderColor: 'var(--border)' }}>
          <a
            href="http://localhost:5173"
            target="_blank"
            rel="noreferrer"
            className="nav-link"
          >
            <ExternalLink size={18} />
            <span className="flex-1">{t('viewStore')}</span>
          </a>
          <button className="nav-link w-full text-left">
            <LogOut size={18} />
            <span>{t('logout')}</span>
          </button>
        </div>
      </aside>
    </>
  );
};

const Topbar = ({ onMenu }: { onMenu: () => void }) => {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const [theme, setTheme] = useState<'light' | 'dark'>(() =>
    document.documentElement.classList.contains('dark') ? 'dark' : 'light',
  );
  const [langOpen, setLangOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [query, setQuery] = useState('');
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) {
        setLangOpen(false);
        setNotifOpen(false);
        setProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const toggleTheme = () => {
    const next = theme === 'light' ? 'dark' : 'light';
    setTheme(next);
    document.documentElement.classList.toggle('dark', next === 'dark');
    localStorage.setItem('maxshop-theme', next);
  };

  const changeLang = (lang: string) => {
    i18n.changeLanguage(lang);
    localStorage.setItem('maxshop-lang', lang);
    setLangOpen(false);
  };

  const submitSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;
    navigate(`/products?q=${encodeURIComponent(query.trim())}`);
    setQuery('');
  };

  return (
    <header
      className="sticky top-0 z-30 border-b bg-[var(--surface)]/85 backdrop-blur-xl"
      style={{ borderColor: 'var(--border)' }}
    >
      <div className="flex h-16 items-center gap-3 px-4 sm:px-6" ref={wrapRef}>
        <button className="icon-btn lg:hidden" onClick={onMenu}>
          <Menu size={18} />
        </button>

        <form onSubmit={submitSearch} className="relative hidden max-w-md flex-1 md:block">
          <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={t('searchPlaceholder')}
            className="input h-10 rounded-xl pl-10 pr-16"
          />
          <span className="absolute right-2.5 top-1/2 hidden -translate-y-1/2 rounded-md border px-1.5 py-0.5 text-[10px] font-bold text-[var(--muted)] lg:block" style={{ borderColor: 'var(--border)' }}>
            Enter
          </span>
        </form>

        <div className="ml-auto flex items-center gap-1.5 sm:gap-2">
          <div className="relative">
            <button className="icon-btn relative" onClick={() => { setNotifOpen((v) => !v); setLangOpen(false); setProfileOpen(false); }} aria-label="notifications">
              <Bell size={18} />
              <span className="absolute right-2 top-2 h-2 w-2 rounded-full bg-rose-500 ring-2 ring-[var(--surface)]" />
            </button>
            {notifOpen && (
              <div className="animate-fade-up absolute right-0 mt-2 w-80 rounded-2xl border bg-[var(--surface)] p-2 shadow-2xl" style={{ borderColor: 'var(--border)' }}>
                <div className="flex items-center justify-between px-2 py-1.5">
                  <p className="text-sm font-extrabold">Bildirishnomalar</p>
                  <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">3 yangi</span>
                </div>
                {notifications.map((n) => (
                  <button key={n.title} className="flex w-full items-start gap-3 rounded-xl p-2.5 text-left transition hover:bg-[var(--surface-2)]">
                    <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[var(--surface-3)] text-base">{n.icon}</span>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-xs font-bold">{n.title}</span>
                      <span className="block truncate text-[11px] text-[var(--muted)]">{n.desc}</span>
                    </span>
                    <span className="shrink-0 text-[10px] font-semibold text-[var(--muted)]">{n.time}</span>
                  </button>
                ))}
                <button className="mt-1 w-full rounded-xl py-2 text-xs font-bold text-brand-600 hover:bg-brand-500/10 dark:text-brand-400">
                  Barchasini o'qilgan deb belgilash
                </button>
              </div>
            )}
          </div>

          <div className="relative">
            <button className="icon-btn" onClick={() => { setLangOpen((v) => !v); setNotifOpen(false); setProfileOpen(false); }} aria-label="language">
              <Globe2 size={18} />
            </button>
            {langOpen && (
              <div className="animate-fade-up absolute right-0 mt-2 w-36 rounded-2xl border bg-[var(--surface)] p-1.5 shadow-2xl" style={{ borderColor: 'var(--border)' }}>
                {[
                  { code: 'uz', label: "O'zbekcha" },
                  { code: 'ru', label: 'Русский' },
                  { code: 'en', label: 'English' },
                ].map((l) => (
                  <button
                    key={l.code}
                    onClick={() => changeLang(l.code)}
                    className={cn(
                      'flex w-full items-center justify-between rounded-xl px-3 py-2 text-xs font-bold transition hover:bg-[var(--surface-2)]',
                      i18n.language === l.code && 'text-brand-600 dark:text-brand-400',
                    )}
                  >
                    {l.label}
                    {i18n.language === l.code && <span>✓</span>}
                  </button>
                ))}
              </div>
            )}
          </div>

          <button className="icon-btn" onClick={toggleTheme} aria-label="theme">
            {theme === 'light' ? <Moon size={18} /> : <Sun size={18} />}
          </button>

          <div className="mx-1 hidden h-8 w-px sm:block" style={{ background: 'var(--border)' }} />

          <div className="relative">
            <button
              className="flex items-center gap-2.5 rounded-xl p-1 pr-2 transition hover:bg-[var(--surface-2)]"
              onClick={() => { setProfileOpen((v) => !v); setNotifOpen(false); setLangOpen(false); }}
            >
              <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-brand-500 to-brand-700 text-sm font-extrabold text-white">
                AR
              </span>
              <span className="hidden text-left sm:block">
                <span className="block text-xs font-extrabold leading-tight">Aziz Rahimov</span>
                <span className="block text-[10px] font-semibold text-[var(--muted)]">Administrator</span>
              </span>
              <ChevronDown size={14} className="hidden text-[var(--muted)] sm:block" />
            </button>
            {profileOpen && (
              <div className="animate-fade-up absolute right-0 mt-2 w-48 rounded-2xl border bg-[var(--surface)] p-1.5 shadow-2xl" style={{ borderColor: 'var(--border)' }}>
                <button onClick={() => { navigate('/settings'); setProfileOpen(false); }} className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold hover:bg-[var(--surface-2)]">
                  <Settings size={14} /> {t('settings')}
                </button>
                <a href="http://localhost:5173" target="_blank" rel="noreferrer" className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold hover:bg-[var(--surface-2)]">
                  <ExternalLink size={14} /> {t('viewStore')}
                </a>
                <button className="flex w-full items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold text-rose-500 hover:bg-rose-500/10">
                  <LogOut size={14} /> {t('logout')}
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
};

export const Layout = ({ children }: { children: React.ReactNode }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  return (
    <div className="min-h-screen">
      <Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <div className="lg:pl-[280px]">
        <Topbar onMenu={() => setSidebarOpen(true)} />
        <main className="mx-auto max-w-[1500px] p-4 sm:p-6 lg:p-8">{children}</main>
      </div>
    </div>
  );
};
